57	   * If the block entry already exists, the chunks will be added to the existing chunks for that block.
58	   *
59	   * @param blockID The ID of the block that these chunks belong to.
60	   * @param chunks A list of chunks to add to this block. The chunks will be sorted internally by their offset.
61	   */
62	  public void addChunks(long blockID, Collection<ChunkInfo> chunks) {
63	    id2Block.computeIfAbsent(blockID, BlockMerkleTree::new).addChunks(chunks);
64	  }
